package Bucles;

public class Ejercicio2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println(" Imprimir del 10 al 1 (While)");
		int n=10;
		while (n>=0) {
			System.out.printf(n + ", ");
			n--;
		}
		System.out.println("Fin");

	}

}
